def sys_msg(text):
    return {"role": "system", "content": text}

def usr_msg(text):
    return {"role": "user", "content": text}

@mcp.prompt()
def draft_reply(ticket_id: str, tone: str = "friendly") -> list[dict]:
    ticket = load_ticket(ticket_id)
    return [sys_msg(f"You are a support agent. Keep replies {tone} and concise."),
            usr_msg(f"Draft a reply to:\n\n{ticket.body}")]

@mcp.prompt()
def summarize_ticket(ticket_id: str) -> list[dict]:
    ticket = load_ticket(ticket_id)
    return [sys_msg("You summarize support tickets in three short bullet points."),
            usr_msg(ticket.body)]

@mcp.prompt()
def escalate_ticket(ticket_id: str, reason: str) -> list[dict]:
    ticket = load_ticket(ticket_id)
    return [sys_msg("You write clear, calm escalation notes for engineering."),
            usr_msg(f"Ticket:\n{ticket.body}\n\nReason for escalation: {reason}")]

