@mcp.prompt()
def summarize_note(note_id: str) -> list[dict]:
    """Summarizes a note in three sentences or fewer."""
    note = load_note(note_id)
    return [
        {"role": "system", "content": "You summarize notes in three sentences or fewer, no more."},
